(()=>{const s=document.createElement('style');s.textContent=`.microscope-instruction{position:relative;z-index:6;margin:0 auto 24px;width:max-content;max-width:calc(100% - 32px);padding:10px 18px;border:2px solid #ffffffb8;border-radius:999px;background:#063b78a8;backdrop-filter:blur(10px);color:#fff;text-align:center;font-size:14px;font-weight:900;box-shadow:0 0 18px #00d9ff66}.microscope-lens{position:fixed;z-index:10000;width:min(330px,72vw);height:min(330px,72vw);border-radius:50%;pointer-events:none;opacity:0;transform:translate(-50%,-50%) scale(.65);transition:.2s;background:radial-gradient(circle at 38% 34%,#ffffff24 0 7%,transparent 22%),radial-gradient(circle,transparent 58%,#001b3a99 78%,#001020e8 100%);border:7px solid #fff;box-shadow:0 0 0 7px #008cff,0 0 42px #00d9ff,0 0 58px #ff8a0080}.microscope-lens:before,.microscope-lens:after{content:"";position:absolute;background:#ffffffa8}.microscope-lens:before{width:1px;height:100%;left:50%}.microscope-lens:after{height:1px;width:100%;top:50%}.microscope-lens.active{opacity:1;transform:translate(-50%,-50%) scale(1)}.microscope-label{position:absolute;left:50%;bottom:12%;transform:translateX(-50%);padding:5px 10px;border-radius:999px;background:#001f45df;color:#fff;font-size:11px;font-weight:900;letter-spacing:1px;white-space:nowrap}.microscope-popup{position:fixed;z-index:10002;left:50%;top:50%;transform:translate(-50%,-50%) scale(.55) rotate(-7deg);opacity:0;pointer-events:none;transition:.22s ease}.microscope-popup.show{opacity:1;transform:translate(-50%,-50%) scale(1) rotate(0)}.microscope-popup svg{width:min(260px,60vw);height:auto;filter:drop-shadow(0 0 10px #fff) drop-shadow(0 0 22px #00d9ff) drop-shadow(0 0 18px #ff8a00)}.microscope-popup-text{margin-top:8px;text-align:center;color:#fff;font-weight:1000;letter-spacing:1.5px;text-shadow:0 0 10px #00d9ff,0 0 16px #ff8a00}.microscope-target{position:relative;z-index:10001!important;transform:scale(1.18)!important;transform-origin:center!important;transition:.2s!important;filter:none!important;box-shadow:none!important;text-shadow:inherit!important;background:inherit!important;color:inherit!important}@media(max-width:760px){.microscope-instruction{font-size:12px;padding:8px 13px}.microscope-target{transform:scale(1.1)!important}}`;document.head.appendChild(s);const hero=document.querySelector('.hero');if(hero){const note=document.createElement('div');note.className='microscope-instruction';note.textContent='Hold the screen or mouse to enter microscope mode.';hero.insertBefore(note,hero.firstChild)}const lens=document.createElement('div');lens.className='microscope-lens';lens.innerHTML='<span class="microscope-label">MICROSCOPE MODE</span>';document.body.appendChild(lens);const popup=document.createElement('div');popup.className='microscope-popup';popup.innerHTML='<svg viewBox="0 0 220 220" aria-hidden="true"><g fill="none" stroke="#ffffff" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"><path d="M94 29h38l8 35-30 7z" fill="#008cff"/><path d="M112 70l-19 44"/><path d="M89 116c18 8 40 4 54-12"/><path d="M132 88c28 14 34 48 20 72"/><path d="M71 165h90"/><path d="M83 165c5-21 20-34 41-39"/><path d="M68 55l23 10"/><circle cx="87" cy="124" r="10" fill="#ff8a00"/></g></svg><div class="microscope-popup-text">ENTERING MICROSCOPE MODE</div>';document.body.appendChild(popup);let holding=false,target=null,timer=null;const selector='h1,h2,h3,p,.eyebrow,.kicker,.credit-label,.institution,.hero-verse,.molecule-link,.paper-button,.comic-panel span,.bottom-band,footer';function move(e){lens.style.left=e.clientX+'px';lens.style.top=e.clientY+'px';if(!holding)return;const el=document.elementFromPoint(e.clientX,e.clientY),next=el&&el.closest(selector);if(next!==target){if(target)target.classList.remove('microscope-target');target=next;if(target)target.classList.add('microscope-target')}}function activate(e){popup.classList.remove('show');move(e);lens.classList.add('active')}function start(e){if(e.button!==undefined&&e.button!==0)return;if(e.target.closest('a,button,.info-card'))return;holding=true;popup.classList.add('show');timer=setTimeout(()=>{if(holding)activate(e)},500)}function stop(){holding=false;clearTimeout(timer);popup.classList.remove('show');lens.classList.remove('active');if(target){target.classList.remove('microscope-target');target=null}}addEventListener('pointermove',move,{passive:true});addEventListener('pointerdown',start,{passive:true});addEventListener('pointerup',stop,{passive:true});addEventListener('pointercancel',stop,{passive:true})})();